INSERT INTO content_sources (id, title, academic_year, origin, status, notes) VALUES ('49754f36-d43c-504f-af33-477e1206f9ea', 'كتاب الكيمياء للصف الثالث الثانوي (نسخة تحريرية)', '2026/2027', 'editorial', 'unverified', 'Needs teacher review. مصاغ بأسلوب أصلي للفصلين: التوازن الكيميائي والأحماض والقواعد.');
INSERT INTO units (id, course_id, title_ar, summary_ar, sort_order, origin, source_id) VALUES ('7c960062-ff07-56c9-80ae-0e3ee40dab5b', '00000000-0000-0000-0000-000000000b02', 'التوازن الكيميائي', 'التفاعلات الانعكاسية وحالة الاتزان الديناميكي، وثابت الاتزان Kc وKp، وحاصل التفاعل Q، وقاعدة لوشاتيليه وتطبيقاتها الصناعية.', 1, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) VALUES ('1273366e-b114-5fa8-a7fb-8b9dc2ecf659', '7c960062-ff07-56c9-80ae-0e3ee40dab5b', 'التفاعلات الانعكاسية وحالة الاتزان', 'نتعرف على التفاعلات التي تسير في الاتجاهين، ونفهم متى يصل النظام إلى حالة الاتزان الديناميكي وكيف نكتب ثابت الاتزان.', '["التمييز بين التفاعل التام والتفاعل الانعكاسي","تفسير حالة الاتزان الديناميكي في نظام مغلق","كتابة تعبير ثابت الاتزان Kc لتفاعل معين"]', '[{"type":"text","text":"بعض التفاعلات تسير في اتجاه واحد حتى تنتهي المتفاعلات تقريبًا، أما التفاعلات الانعكاسية فتسير في الاتجاهين: المتفاعلات تتحول إلى نواتج (التفاعل الأمامي)، والنواتج تعود فتتحول إلى متفاعلات (التفاعل العكسي). نرمز لها بسهمين متعاكسين ⇌."},{"type":"formula","tex":"N_2(g) + 3H_2(g) \\rightleftharpoons 2NH_3(g)"},{"type":"text","text":"عند بدء التفاعل تكون سرعة التفاعل الأمامي كبيرة وسرعة العكسي صغيرة (أو صفرًا). مع مرور الزمن تقل تراكيز المتفاعلات فتقل سرعة التفاعل الأمامي، وتزداد تراكيز النواتج فتزداد سرعة التفاعل العكسي، إلى أن تتساوى السرعتان فيصل النظام إلى حالة الاتزان."},{"type":"note","text":"الاتزان ديناميكي وليس ساكنًا: التفاعلان الأمامي والعكسي مستمران، لكن بسرعتين متساويتين، لذلك تبقى التراكيز ثابتة ولا يظهر أي تغير ملحوظ. ولا يتحقق الاتزان إلا في نظام مغلق لا تفلت منه المواد."},{"type":"text","text":"لا يعني الاتزان أن تراكيز المتفاعلات تساوي تراكيز النواتج، بل يعني أنها ثابتة عند قيم معينة تعتمد على طبيعة التفاعل ودرجة الحرارة."}]', 1, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('cde62b6d-4c5e-520d-a103-1c695b2b9275', '1273366e-b114-5fa8-a7fb-8b9dc2ecf659', 'التفاعلات الانعكاسية والاتزان الديناميكي', 'التفاعل الانعكاسي هو تفاعل تتحول فيه المتفاعلات إلى نواتج وتتحول النواتج إلى متفاعلات في الوقت نفسه. عندما تتساوى سرعة التفاعل الأمامي مع سرعة التفاعل العكسي في نظام مغلق عند درجة حرارة ثابتة، تثبت تراكيز جميع المواد ويسمى النظام في حالة اتزان ديناميكي.', '\text{rate}_{forward} = \text{rate}_{reverse}', 1, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('ea8b0c0b-dcb1-545e-8cf7-40c822fbbea3', 'cde62b6d-4c5e-520d-a103-1c695b2b9275', 'أي العبارات الآتية تصف حالة الاتزان الكيميائي بدقة؟', 'عند الاتزان تتساوى سرعتا التفاعلين فتثبت التراكيز، ولا يتوقف أي منهما.', 1, 'editorial'),
 ('86e9914c-e1d3-5198-943f-e203e26ba74d', 'cde62b6d-4c5e-520d-a103-1c695b2b9275', 'يوصف الاتزان الكيميائي بأنه ديناميكي لأن:', 'الديناميكية تعني استمرار التفاعلين على المستوى الجزيئي مع ثبات التراكيز الكلية.', 1, 'editorial'),
 ('5646ff06-3e09-5993-aaea-0480dca4d4f5', 'cde62b6d-4c5e-520d-a103-1c695b2b9275', 'أي التفاعلات الآتية يعد تفاعلًا انعكاسيًا في وعاء مغلق؟', 'تفاعل تكوين النشادر (هابر) انعكاسي، أما الاحتراق وتفاعل الصوديوم مع الماء فتفاعلات تامة عمليًا.', 1, 'editorial'),
 ('4654178b-d367-54f6-90bf-7a36f754ebb3', 'cde62b6d-4c5e-520d-a103-1c695b2b9275', 'عند وصول نظام مغلق إلى الاتزان عند درجة حرارة ثابتة، أي العبارات صحيحة؟', 'ثبات التراكيز هو المظهر العملي للاتزان، ولا يشترط تساويها.', 2, 'editorial'),
 ('fe080bfa-efbe-5489-bff9-92d80488ab97', 'cde62b6d-4c5e-520d-a103-1c695b2b9275', 'لماذا يلزم نظام مغلق لتحقيق الاتزان في التفاعل CaCO₃(s) ⇌ CaO(s) + CO₂(g)؟', 'في الوعاء المفتوح يخرج CO₂ فلا يحدث التفاعل العكسي ولا يتحقق الاتزان.', 2, 'editorial'),
 ('4bb838b1-b69b-54c7-8491-8711ed0c1ff6', 'cde62b6d-4c5e-520d-a103-1c695b2b9275', 'في التفاعل 2NO₂ (بني) ⇌ N₂O₄ (عديم اللون)، ثبات لون الخليط عند الاتزان يدل على أن:', 'ثبات اللون يعني ثبات التراكيز، وهذا ينتج عن تساوي سرعتي التفاعلين الأمامي والعكسي.', 3, 'editorial');
