 ('bd2837e2-3d29-594d-bd0a-6662f725103b', '4bb838b1-b69b-54c7-8491-8711ed0c1ff6', 'سرعة تكوّن N₂O₄ تساوي سرعة تفككه', 1, 1),
 ('fdf22f5a-313b-5417-b08e-10e1301d5205', '4bb838b1-b69b-54c7-8491-8711ed0c1ff6', 'التفاعل توقف نهائيًا', 0, 2),
 ('8c65577f-15be-5685-be93-bf1ca5a3c339', '4bb838b1-b69b-54c7-8491-8711ed0c1ff6', 'كل NO₂ تحول إلى N₂O₄', 0, 3),
 ('5663d40e-dfc1-5c1e-af75-1d877c79c11b', '4bb838b1-b69b-54c7-8491-8711ed0c1ff6', 'عدد مولات NO₂ يساوي عدد مولات N₂O₄', 0, 4);
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('ff8a183c-020a-5e72-b8ad-52c10d02c19a', '1273366e-b114-5fa8-a7fb-8b9dc2ecf659', 'ثابت الاتزان Kc وكتابة تعبيره', 'للتفاعل aA + bB ⇌ cC + dD عند الاتزان يكون ثابت الاتزان Kc = [C]^c [D]^d / ([A]^a [B]^b) حيث الأقواس المربعة تعني التركيز المولاري عند الاتزان، والأسس هي معاملات الموازنة. لا تكتب المواد الصلبة النقية والسوائل النقية في التعبير لأن تركيزها ثابت. وعند عكس التفاعل يصبح الثابت مقلوب القيمة الأصلية، وعند ضرب معاملات المعادلة في عدد n يرفع الثابت إلى القوة n.', 'K_c = \dfrac{[C]^c\,[D]^d}{[A]^a\,[B]^b}', 2, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('dd655889-48fd-5250-9e88-737b754dc836', 'ff8a183c-020a-5e72-b8ad-52c10d02c19a', 'تعبير ثابت الاتزان Kc للتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) هو:', 'النواتج في البسط والمتفاعلات في المقام، وكل تركيز مرفوع إلى معامله في المعادلة الموزونة.', 1, 'editorial'),
 ('a27150ff-b2f6-5538-b32d-a53a10e6d9ea', 'ff8a183c-020a-5e72-b8ad-52c10d02c19a', 'تعبير Kc للتفاعل H₂(g) + I₂(g) ⇌ 2HI(g) هو:', '[HI] مرفوعة للقوة 2 في البسط، و[H₂] و[I₂] في المقام.', 1, 'editorial'),
 ('642b2f5d-bc67-5100-9b23-9f7e43bbee92', 'ff8a183c-020a-5e72-b8ad-52c10d02c19a', 'المواد التي لا تكتب في تعبير ثابت الاتزان Kc هي:', 'تركيز المادة الصلبة أو السائلة النقية ثابت (كثافتها ثابتة) فيدخل في قيمة Kc.', 1, 'editorial'),
 ('db73c49e-cbc4-555d-96be-9a98568ab984', 'ff8a183c-020a-5e72-b8ad-52c10d02c19a', 'تعبير Kc للتفاعل CaCO₃(s) ⇌ CaO(s) + CO₂(g) هو:', 'CaCO₃ وCaO مادتان صلبتان فلا تظهران، ويبقى تركيز الغاز CO₂ فقط.', 2, 'editorial'),
 ('309a1c25-533d-5f7c-b31c-e097cac0e41f', 'ff8a183c-020a-5e72-b8ad-52c10d02c19a', 'إذا كانت قيمة Kc للتفاعل A ⇌ B تساوي 4 عند درجة حرارة معينة، فإن Kc للتفاعل العكسي B ⇌ A عند الدرجة نفسها تساوي:', 'عكس التفاعل يقلب التعبير: Kc'' = 1 / Kc = 1 / 4 = 0.25.', 2, 'editorial'),
 ('b9e77f7a-101f-5cfa-8be6-76360c1205ad', 'ff8a183c-020a-5e72-b8ad-52c10d02c19a', 'قيمة Kc للتفاعل N₂ + 3H₂ ⇌ 2NH₃ تساوي 36 عند درجة حرارة معينة. ما قيمة Kc للتفاعل ½N₂ + 3/2 H₂ ⇌ NH₃ عند الدرجة نفسها؟', 'عند قسمة معاملات المعادلة على 2 يصبح الثابت الجديد = √36 = 6.', 3, 'editorial');
INSERT INTO question_options (id, question_id, label_ar, is_correct, sort_order) VALUES
 ('6732c008-2c05-53bd-b9e3-923bfc6f2bab', 'dd655889-48fd-5250-9e88-737b754dc836', 'Kc = [N₂][H₂]³ / [NH₃]²', 0, 1),
