 ('07e6d8e3-7aa6-5476-a443-8c716930f9e0', 'a27150ff-b2f6-5538-b32d-a53a10e6d9ea', 'Kc = [HI]² / ([H₂][I₂])', 1, 3),
 ('70d722e8-5a97-5209-9e3d-b64d87e241f3', 'a27150ff-b2f6-5538-b32d-a53a10e6d9ea', 'Kc = 2[HI] / ([H₂] + [I₂])', 0, 4),
 ('7e3943f7-7cf1-554a-8c83-4858e3fbfbd9', '642b2f5d-bc67-5100-9b23-9f7e43bbee92', 'جميع الغازات', 0, 1),
 ('5f47f79f-1942-5cd9-b4a5-43b6bbe49f9f', '642b2f5d-bc67-5100-9b23-9f7e43bbee92', 'المواد الصلبة النقية والسوائل النقية', 1, 2),
 ('309cd864-1bb2-5e95-8cbb-6de897ff01b6', '642b2f5d-bc67-5100-9b23-9f7e43bbee92', 'جميع المواد المتفاعلة', 0, 3),
 ('23c5f5a3-b2cd-5880-8fd1-2b32036aeec4', '642b2f5d-bc67-5100-9b23-9f7e43bbee92', 'المواد الذائبة في الماء', 0, 4),
 ('38dc1618-4a16-581c-bf17-a8ab051a6174', 'db73c49e-cbc4-555d-96be-9a98568ab984', 'Kc = [CO₂]', 1, 1),
 ('46732f4c-db67-5bee-891a-02787dc83906', 'db73c49e-cbc4-555d-96be-9a98568ab984', 'Kc = [CaO][CO₂] / [CaCO₃]', 0, 2),
 ('5a385b7b-b132-563e-94ca-5b3fcb7c33e7', 'db73c49e-cbc4-555d-96be-9a98568ab984', 'Kc = [CaCO₃] / [CaO][CO₂]', 0, 3),
 ('5f114e53-221f-5446-bae5-987a2fb63123', 'db73c49e-cbc4-555d-96be-9a98568ab984', 'Kc = [CaO] / [CaCO₃]', 0, 4),
 ('aa246fb5-edfc-5b0a-8cb0-9be6c7256f48', '309a1c25-533d-5f7c-b31c-e097cac0e41f', '4', 0, 1),
 ('7b505e72-ce2a-57fb-8875-105373b9b925', '309a1c25-533d-5f7c-b31c-e097cac0e41f', '16', 0, 2),
 ('490dd988-6505-51b6-8534-cda0eb918f1e', '309a1c25-533d-5f7c-b31c-e097cac0e41f', '-4', 0, 3),
