 ('47c33c5a-c9b5-5e9a-892f-fcfac38fafe8', 'b9e77f7a-101f-5cfa-8be6-76360c1205ad', '6', 1, 3),
 ('9efc2b71-40a9-5b64-bfa8-64d4c2e6659e', 'b9e77f7a-101f-5cfa-8be6-76360c1205ad', '1296', 0, 4);
INSERT INTO lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) VALUES ('6b1b0912-9c23-5850-8795-b318a6d8f856', '7c960062-ff07-56c9-80ae-0e3ee40dab5b', 'حساب ثابت الاتزان والتراكيز عند الاتزان', 'نتدرب على حساب قيمة Kc من التراكيز عند الاتزان، وإيجاد تركيز مجهول، واستخدام جدول التغير (ICE).', '["حساب Kc من التراكيز أو المولات عند الاتزان","إيجاد تركيز مجهول عند الاتزان باستخدام Kc","استخدام جدول (البداية - التغير - الاتزان) في الحسابات"]', '[{"type":"text","text":"لحساب Kc: (1) اكتب المعادلة الموزونة وتعبير Kc، (2) حوّل كل كمية إلى تركيز مولاري (mol/L) بقسمة عدد المولات على حجم الوعاء باللتر، (3) عوّض بالتراكيز عند الاتزان فقط."},{"type":"formula","tex":"K_c = \\dfrac{[HI]^2}{[H_2][I_2]} = \\dfrac{(0.4)^2}{(0.1)(0.1)} = 16"},{"type":"note","text":"خطأ شائع: التعويض بعدد المولات مباشرة بدل التركيز. إذا كان حجم الوعاء لا يساوي 1 لتر فلا بد من القسمة على الحجم أولًا، إلا في التفاعلات التي يتساوى فيها عدد مولات الغازات على الجانبين."},{"type":"text","text":"تدل قيمة Kc على مدى تقدم التفاعل: إذا كانت Kc كبيرة جدًا (أكبر بكثير من 1) فالنواتج هي الغالبة عند الاتزان، وإذا كانت صغيرة جدًا (أقل بكثير من 1) فالمتفاعلات هي الغالبة. ولا تدل Kc على سرعة الوصول للاتزان."},{"type":"text","text":"جدول ICE: نكتب التراكيز الابتدائية (I)، ثم التغير (C) بدلالة x حسب معاملات المعادلة، ثم تراكيز الاتزان (E)، ونعوض في تعبير Kc لحساب x."}]', 2, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('309545d4-ed6e-5ee7-be1d-9223d5589d84', '6b1b0912-9c23-5850-8795-b318a6d8f856', 'حساب Kc من التراكيز عند الاتزان', 'نعوّض بتراكيز المواد عند الاتزان (mol/L) في تعبير Kc. إذا أعطيت كميات بالمول فنقسمها على حجم الوعاء. القيمة الكبيرة لـ Kc تعني أن النواتج مفضلة عند الاتزان، والقيمة الصغيرة تعني أن المتفاعلات مفضلة.', 'K_c = \dfrac{[\text{النواتج}]}{[\text{المتفاعلات}]}', 1, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('d1741fb7-b557-56c3-adcb-5720fd31406a', '309545d4-ed6e-5ee7-be1d-9223d5589d84', 'عند الاتزان للتفاعل H₂ + I₂ ⇌ 2HI كانت التراكيز: [H₂] = 0.1 M و[I₂] = 0.1 M و[HI] = 0.4 M. ما قيمة Kc؟', 'Kc = (0.4)² / (0.1 × 0.1) = 0.16 / 0.01 = 16.', 1, 'editorial'),
 ('c7dfe218-a761-5daf-ba1c-ef79a5bb2e6b', '309545d4-ed6e-5ee7-be1d-9223d5589d84', 'في التفاعل N₂ + 3H₂ ⇌ 2NH₃ كانت تراكيز الاتزان: [N₂] = 0.5 M و[H₂] = 2 M و[NH₃] = 4 M. ما قيمة Kc؟', 'Kc = (4)² / (0.5 × 2³) = 16 / (0.5 × 8) = 16 / 4 = 4.', 2, 'editorial'),
 ('df3d5428-0ab5-562f-a191-7183913e5b74', '309545d4-ed6e-5ee7-be1d-9223d5589d84', 'إذا كانت Kc لتفاعل تساوي 1 × 10⁵ عند درجة حرارة معينة فهذا يعني أنه عند الاتزان:', 'قيمة Kc الكبيرة تعني أن بسط التعبير (النواتج) أكبر كثيرًا من المقام (المتفاعلات).', 2, 'editorial'),
 ('ab2f4537-3f26-5051-b09f-ccb4d99c907e', '309545d4-ed6e-5ee7-be1d-9223d5589d84', 'عند الاتزان للتفاعل 2SO₂ + O₂ ⇌ 2SO₃ كانت التراكيز: [SO₂] = 0.2 M و[O₂] = 0.5 M و[SO₃] = 0.4 M. ما قيمة Kc؟', 'Kc = (0.4)² / ((0.2)² × 0.5) = 0.16 / (0.04 × 0.5) = 0.16 / 0.02 = 8.', 2, 'editorial'),
 ('9ee24f49-c8cf-5280-89b9-d4a49b11d9cf', '309545d4-ed6e-5ee7-be1d-9223d5589d84', 'في وعاء حجمه 2 لتر وصل التفاعل 2NO₂ ⇌ N₂O₄ إلى الاتزان وفيه 1.0 mol من NO₂ و1.0 mol من N₂O₄. ما قيمة Kc؟', 'التراكيز: [NO₂] = 1/2 = 0.5 M و[N₂O₄] = 0.5 M. Kc = 0.5 / (0.5)² = 0.5 / 0.25 = 2.', 3, 'editorial'),
 ('3e014e96-159d-515f-8e53-a410d4959378', '309545d4-ed6e-5ee7-be1d-9223d5589d84', 'في وعاء حجمه 2 لتر وصل التفاعل PCl₅ ⇌ PCl₃ + Cl₂ إلى الاتزان وفيه 0.4 mol من PCl₅ و0.2 mol من PCl₃ و0.2 mol من Cl₂. ما قيمة Kc؟', 'التراكيز: [PCl₅] = 0.2 M و[PCl₃] = [Cl₂] = 0.1 M. Kc = (0.1 × 0.1) / 0.2 = 0.01 / 0.2 = 0.05.', 3, 'editorial');
