INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('87c4648f-b6a5-5ba8-9f95-a8e1bb4e8013', '6b1b0912-9c23-5850-8795-b318a6d8f856', 'حساب التراكيز المجهولة وجدول ICE', 'إذا عُرفت Kc وبعض التراكيز عند الاتزان نستطيع حساب التركيز المجهول بالتعويض في تعبير Kc. وعند معرفة التراكيز الابتدائية نستخدم جدول ICE: نفرض أن x هو مقدار التغير، ونكتب تراكيز الاتزان بدلالة x حسب نسب المعاملات، ثم نحل المعادلة الناتجة.', 'K_c = \dfrac{(2x)^2}{(1-x)^2}', 2, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('e85062bc-d666-53fc-91d9-8813fefd82a7', '87c4648f-b6a5-5ba8-9f95-a8e1bb4e8013', 'للتفاعل H₂ + I₂ ⇌ 2HI قيمة Kc = 50 عند درجة معينة. إذا كان [H₂] = 0.1 M و[I₂] = 0.2 M عند الاتزان، فما قيمة [HI]؟', '[HI]² = Kc × [H₂][I₂] = 50 × 0.02 = 1، إذن [HI] = 1 M.', 1, 'editorial'),
 ('5c67eac5-a48b-5f4d-9a7c-6de796d96c57', '87c4648f-b6a5-5ba8-9f95-a8e1bb4e8013', 'للتفاعل N₂O₄ ⇌ 2NO₂ قيمة Kc = 0.04. إذا كان [N₂O₄] = 0.25 M عند الاتزان، فما قيمة [NO₂]؟', '[NO₂]² = Kc × [N₂O₄] = 0.04 × 0.25 = 0.01، إذن [NO₂] = 0.1 M.', 2, 'editorial'),
 ('738710bc-9bcb-5aa3-b0b5-3975f29dc6c2', '87c4648f-b6a5-5ba8-9f95-a8e1bb4e8013', 'بدأ تفاعل H₂ + I₂ ⇌ 2HI بتركيز 1 M من كل من H₂ وI₂ ولا يوجد HI، وكانت Kc = 4. ما تركيز HI عند الاتزان؟', '(2x)² / (1 - x)² = 4 ومنها 2x / (1 - x) = 2 فتكون x = 0.5، إذن [HI] = 2x = 1 M. تحقق: 1² / (0.5 × 0.5) = 4.', 2, 'editorial'),
 ('a448c789-c411-5c61-927f-2c2fd1e5758f', '87c4648f-b6a5-5ba8-9f95-a8e1bb4e8013', 'بدأ التفاعل CO + H₂O ⇌ CO₂ + H₂ بتركيز 1 M من CO و1 M من H₂O، وقيمة Kc = 9. ما تركيز CO عند الاتزان؟', 'x² / (1 - x)² = 9 ومنها x / (1 - x) = 3 فتكون x = 0.75، إذن [CO] = 1 - 0.75 = 0.25 M. تحقق: (0.75)² / (0.25)² = 9.', 3, 'editorial'),
 ('2847fed4-af57-5d5d-8b05-000c4c50196f', '87c4648f-b6a5-5ba8-9f95-a8e1bb4e8013', 'بدأ تفاعل 2HI ⇌ H₂ + I₂ بتركيز 1 M من HI فقط، وعند الاتزان وجد أن [H₂] = 0.1 M. ما قيمة Kc؟', 'تفكك 0.2 M من HI فبقي [HI] = 0.8 M وتكوّن [H₂] = [I₂] = 0.1 M. Kc = (0.1 × 0.1) / (0.8)² = 0.01 / 0.64 ≈ 0.0156.', 3, 'editorial'),
 ('eb606d8e-caff-5087-819f-b4c875ed880e', '87c4648f-b6a5-5ba8-9f95-a8e1bb4e8013', 'في وعاء حجمه 1 لتر وضع 1 mol من N₂ و3 mol من H₂، وعند الاتزان وجد 0.4 mol من NH₃. ما تركيز H₂ عند الاتزان؟', 'تكوين 0.4 mol NH₃ يستهلك 0.2 mol N₂ و0.6 mol H₂ حسب المعادلة N₂ + 3H₂ ⇌ 2NH₃، إذن [H₂] = 3 - 0.6 = 2.4 M.', 2, 'editorial');
