 ('434f9423-b445-500f-b56c-3570dc9a223a', 'eb606d8e-caff-5087-819f-b4c875ed880e', '1.8 M', 0, 4);
INSERT INTO lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) VALUES ('a66d8681-d5e4-5861-8239-c37795ab9759', '7c960062-ff07-56c9-80ae-0e3ee40dab5b', 'قاعدة لوشاتيليه وتأثير العوامل على الاتزان', 'نتنبأ باتجاه انزياح الاتزان عند تغيير التركيز أو الضغط أو درجة الحرارة، ونفرّق بين تأثير العامل الحفاز وتأثير بقية العوامل.', '["نص قاعدة لوشاتيليه وتطبيقها على التركيز والضغط","تحديد أثر درجة الحرارة على موضع الاتزان وقيمة Kc","توضيح دور العامل الحفاز في الاتزان"]', '[{"type":"text","text":"قاعدة لوشاتيليه: إذا أثّر عامل خارجي على نظام في حالة اتزان فإن النظام ينزاح في الاتجاه الذي يقلل من تأثير هذا العامل ليصل إلى اتزان جديد."},{"type":"text","text":"التركيز: زيادة تركيز مادة تزحزح الاتزان في الاتجاه الذي يستهلكها، ونقصان تركيزها (بسحبها من الوسط) يزحزح الاتزان في الاتجاه الذي يعوضها."},{"type":"text","text":"الضغط (للغازات): زيادة الضغط بتقليل الحجم تزحزح الاتزان نحو الجهة ذات العدد الأقل من مولات الغاز، وخفض الضغط يزحزحه نحو العدد الأكبر. وإذا تساوى عدد المولات الغازية على الجانبين فلا تأثير للضغط."},{"type":"text","text":"درجة الحرارة: رفع الحرارة يزحزح الاتزان في الاتجاه الماص للحرارة، وخفضها يزحزحه في الاتجاه الطارد للحرارة. وهي العامل الوحيد الذي يغير قيمة Kc."},{"type":"formula","tex":"N_2 + 3H_2 \\rightleftharpoons 2NH_3 \\qquad \\Delta H = -92\\ \\text{kJ}"},{"type":"note","text":"العامل الحفاز يزيد سرعة التفاعلين الأمامي والعكسي بالمقدار نفسه، فيصل النظام إلى الاتزان أسرع، لكنه لا يغير موضع الاتزان ولا قيمة Kc ولا كمية الناتج النهائية."}]', 3, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('4f01cd76-d4ca-55d3-a3b0-c1b93a912b9a', 'a66d8681-d5e4-5861-8239-c37795ab9759', 'تأثير التركيز والضغط على الاتزان', 'تغير التركيز أو الضغط يزحزح موضع الاتزان لكنه لا يغير قيمة Kc عند ثبوت درجة الحرارة. عند زيادة تركيز مادة ينزاح الاتزان بعيدًا عنها، وعند زيادة الضغط ينزاح نحو الجهة ذات مولات الغاز الأقل. إذا تساوت مولات الغازات في الطرفين فلا يتأثر الاتزان بالضغط.', '\Delta n_g = n_{g(\text{نواتج})} - n_{g(\text{متفاعلات})}', 1, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('a79e7bcf-6390-51f1-b5ec-85172ac5045b', '4f01cd76-d4ca-55d3-a3b0-c1b93a912b9a', 'ينص مبدأ لوشاتيليه على أن النظام المتزن إذا تعرض لعامل خارجي:', 'هذا هو نص القاعدة: يعمل النظام على مقاومة التغير الخارجي جزئيًا.', 1, 'editorial'),
 ('9a5aa823-df65-5656-93f2-dfbf1ba37f77', '4f01cd76-d4ca-55d3-a3b0-c1b93a912b9a', 'في التفاعل N₂ + 3H₂ ⇌ 2NH₃ عند زيادة تركيز N₂ يحدث:', 'زيادة تركيز أحد المتفاعلات تدفع النظام لاستهلاكه، أي نحو تكوين النواتج.', 1, 'editorial'),
 ('4d1866bf-53a2-5d2a-be3e-8bc581db0e26', '4f01cd76-d4ca-55d3-a3b0-c1b93a912b9a', 'في التفاعل N₂ + 3H₂ ⇌ 2NH₃ تؤدي زيادة الضغط (بتقليل الحجم) إلى:', 'عدد مولات الغاز في المتفاعلات 4 وفي النواتج 2، والضغط المرتفع يفضل الجهة الأقل عددًا.', 2, 'editorial'),
 ('0d6556fe-9fb2-5ce9-a4d7-52e6a6ffc5ed', '4f01cd76-d4ca-55d3-a3b0-c1b93a912b9a', 'أي التفاعلات الآتية لا يتأثر موضع اتزانه بتغير الضغط؟', 'عدد مولات الغاز متساوٍ على الجانبين (2 = 2) في تفاعل HI فلا تأثير للضغط.', 2, 'editorial'),
 ('fe2556c3-ff71-54f4-bbf8-b1e409c72b09', '4f01cd76-d4ca-55d3-a3b0-c1b93a912b9a', 'في التفاعل PCl₅(g) ⇌ PCl₃(g) + Cl₂(g) تؤدي زيادة الضغط إلى:', 'الجهة اليسرى فيها مول غاز واحد والجهة اليمنى فيها مولان، فيفضل الضغط المرتفع اليسار.', 2, 'editorial'),
 ('5dae5b9a-705b-5915-ba46-acf5b112a264', '4f01cd76-d4ca-55d3-a3b0-c1b93a912b9a', 'في صناعة النشادر بطريقة هابر يُسحب NH₃ من وعاء التفاعل باستمرار بتسييله. الهدف من ذلك:', 'سحب الناتج يقلل تركيزه فينزاح الاتزان نحو تعويضه، أي يزداد إنتاج NH₃.', 2, 'editorial'),
 ('19d6e84b-0126-51ed-a23d-e70663b6f2d5', '4f01cd76-d4ca-55d3-a3b0-c1b93a912b9a', 'عند إضافة N₂ إلى النظام المتزن N₂ + 3H₂ ⇌ 2NH₃ عند درجة حرارة ثابتة، فإن قيمة Kc بعد الوصول إلى اتزان جديد:', 'Kc تتغير بتغير درجة الحرارة فقط، أما تغير التركيز فيغير موضع الاتزان مع بقاء Kc ثابتة.', 3, 'editorial');
