INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('fe16078b-6888-501e-ad75-f4429d825b13', 'a66d8681-d5e4-5861-8239-c37795ab9759', 'تأثير درجة الحرارة والعامل الحفاز', 'رفع درجة الحرارة يفضل التفاعل الماص للحرارة ويزيد Kc إذا كان التفاعل الأمامي ماصًا، أما إذا كان الأمامي طاردًا فترتفع الحرارة فتقل Kc. العامل الحفاز يسرّع الوصول للاتزان فقط ولا يغير Kc ولا موضع الاتزان. في الصناعة تختار ظروف وسطًا (حرارة وضغط وحفاز) توازن بين كمية الناتج وسرعة التفاعل.', '\text{رفع } T \Rightarrow \text{ينزاح نحو الاتجاه الماص}', 2, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('de7a1a85-b788-57f8-ac73-aaf580edc32f', 'fe16078b-6888-501e-ad75-f4429d825b13', 'تفاعل ماص للحرارة عند الاتزان، فإن رفع درجة الحرارة:', 'الاتجاه الأمامي ماص للحرارة، ورفع الحرارة يفضل الاتجاه الماص فتزداد النواتج وتزداد Kc.', 1, 'editorial'),
 ('ff0298c1-97e2-56de-a68a-e5da30f086fd', 'fe16078b-6888-501e-ad75-f4429d825b13', 'أثر العامل الحفاز على تفاعل انعكاسي هو:', 'يخفض الحفاز طاقة التنشيط للتفاعلين الأمامي والعكسي بالقدر نفسه.', 1, 'editorial'),
 ('1f125881-97dc-5c39-aaf4-7f3579f5c826', 'fe16078b-6888-501e-ad75-f4429d825b13', 'في تفاعل هابر N₂ + 3H₂ ⇌ 2NH₃ (ΔH = -92 kJ) يؤدي تبريد الخليط إلى:', 'التفاعل الأمامي طارد للحرارة، والتبريد يفضل الاتجاه الطارد فتزداد النواتج وتزداد Kc.', 2, 'editorial'),
 ('3a07e9d7-78a3-5c87-880b-7a00b2b84eb2', 'fe16078b-6888-501e-ad75-f4429d825b13', 'الغاز البني NO₂ يتحول إلى N₂O₄ عديم اللون: 2NO₂ ⇌ N₂O₄ والتفاعل الأمامي طارد للحرارة. عند تسخين الدورق المحتوي على الخليط المتزن:', 'التسخين يفضل الاتجاه الماص (العكسي) فيتفكك N₂O₄ إلى NO₂ البني.', 2, 'editorial'),
 ('79214a44-6c9e-5a4f-b78c-b5bf84e45c81', 'fe16078b-6888-501e-ad75-f4429d825b13', 'في التفاعل N₂O₄(g) ⇌ 2NO₂(g) (ΔH = +57 kJ) أي الظروف الآتية تزيد من كمية NO₂ عند الاتزان؟', 'التفاعل ماص فتفضله الحرارة المرتفعة، والنواتج فيها مولان غازيان مقابل مول واحد فيفضلها الضغط المنخفض.', 3, 'editorial'),
 ('38ee54fb-8fb4-50ba-ac46-8e6980ee3beb', 'fe16078b-6888-501e-ad75-f4429d825b13', 'في تحضير SO₃ بطريقة التلامس 2SO₂ + O₂ ⇌ 2SO₃ (طارد للحرارة) يستخدم V₂O₅ عند حوالي 450 °C بدلًا من درجة حرارة منخفضة جدًا. السبب:', 'الحرارة المنخفضة تفضل الناتج نظريًا لكنها تبطئ التفاعل، فتختار حرارة وسطًا مع حفاز لتحقيق إنتاج مناسب بسرعة مقبولة.', 3, 'editorial');
INSERT INTO question_options (id, question_id, label_ar, is_correct, sort_order) VALUES
