 ('fec316fe-52ae-53b5-a99e-90ff00a74d5d', '1f125881-97dc-5c39-aaf4-7f3579f5c826', 'نقص كمية NH₃ وزيادة قيمة Kc', 0, 2),
 ('169b04bd-84aa-52c1-a051-cc8adda8f787', '1f125881-97dc-5c39-aaf4-7f3579f5c826', 'زيادة كمية NH₃ مع بقاء Kc ثابتة', 0, 3),
 ('c157106b-927f-541a-8ed2-d61cff924106', '1f125881-97dc-5c39-aaf4-7f3579f5c826', 'نقص كمية NH₃ ونقص قيمة Kc', 0, 4),
