 ('f001cb31-d068-57f7-87ec-bf17d5052041', '3a07e9d7-78a3-5c87-880b-7a00b2b84eb2', 'لا يتغير اللون', 0, 2),
 ('86658742-3c73-590c-bf82-8c8093daf9ee', '3a07e9d7-78a3-5c87-880b-7a00b2b84eb2', 'يصبح الخليط عديم اللون تمامًا', 0, 3),
 ('01c071d2-9f43-5c97-a93b-ffe7f0170b82', '3a07e9d7-78a3-5c87-880b-7a00b2b84eb2', 'يزداد اللون البني غمقًا', 1, 4),
