 ('de3e617e-fb1f-50c3-ae2b-e5ce8b0b7170', '38ee54fb-8fb4-50ba-ac46-8e6980ee3beb', 'لأن رفع الحرارة يزيد قيمة Kc لهذا التفاعل', 0, 1),
 ('882cded6-c84c-5795-85cd-f7d7c7eef43b', '38ee54fb-8fb4-50ba-ac46-8e6980ee3beb', 'لأن الحرارة المنخفضة جدًا تجعل التفاعل بطيئًا، والحفاز يسرعه عند درجة معتدلة', 1, 2),
 ('27a24feb-39b7-5d1f-a1b4-1ae22827472c', '38ee54fb-8fb4-50ba-ac46-8e6980ee3beb', 'لأن الحفاز يزيح الاتزان نحو SO₃', 0, 3),
 ('277d0c59-4811-50b9-ad80-7aef0ef4a8c8', '38ee54fb-8fb4-50ba-ac46-8e6980ee3beb', 'لأن SO₃ لا يتكون إلا فوق 450 °C', 0, 4);
INSERT INTO lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) VALUES ('a7c6822d-2cbd-53ed-8890-17f4a112fe0d', '7c960062-ff07-56c9-80ae-0e3ee40dab5b', 'حاصل التفاعل Q وثابت الضغط Kp', 'نستخدم حاصل التفاعل Q للتنبؤ باتجاه سير التفاعل، ونتعلم ثابت الاتزان بدلالة الضغوط Kp وعلاقته بـ Kc.', '["مقارنة Q بـ Kc للتنبؤ باتجاه التفاعل","كتابة تعبير Kp وحسابه من الضغوط الجزئية","استخدام العلاقة بين Kp وKc"]', '[{"type":"text","text":"حاصل التفاعل Q له صيغة Kc نفسها لكنه يُحسب بالتراكيز في أي لحظة، وليس بالضرورة عند الاتزان. بمقارنة Q بـ Kc نعرف في أي اتجاه يسير التفاعل ليصل إلى الاتزان."},{"type":"formula","tex":"Q < K_c \\Rightarrow \\text{أمامي} \\qquad Q = K_c \\Rightarrow \\text{اتزان} \\qquad Q > K_c \\Rightarrow \\text{عكسي}"},{"type":"text","text":"إذا كانت Q أصغر من Kc فالنواتج أقل من اللازم فيسير التفاعل أماميًا لتكوين المزيد منها. وإذا كانت Q أكبر من Kc فالنواتج زائدة فيسير التفاعل عكسيًا."},{"type":"text","text":"في التفاعلات الغازية يمكن التعبير عن الاتزان بالضغوط الجزئية (بوحدة atm مثلًا) فنحصل على Kp. الضغط الجزئي لغاز في خليط = الكسر المولي × الضغط الكلي."},{"type":"formula","tex":"K_p = K_c\\,(RT)^{\\Delta n}"},{"type":"note","text":"Δn = مجموع معاملات النواتج الغازية - مجموع معاملات المتفاعلات الغازية. إذا كانت Δn = 0 فإن Kp = Kc. والمواد الصلبة والسائلة لا تظهر في تعبير Kp أيضًا."}]', 4, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('43704526-882c-5335-b251-9984e7c529b3', 'a7c6822d-2cbd-53ed-8890-17f4a112fe0d', 'حاصل التفاعل Q واتجاه سير التفاعل', 'Q تحسب بتعويض التراكيز اللحظية في تعبير Kc. إذا كانت Q < Kc يسير التفاعل في الاتجاه الأمامي، وإذا كانت Q > Kc يسير في الاتجاه العكسي، وإذا تساوتا فالنظام في اتزان ولا يتغير شيء.', 'Q = \dfrac{[C]^c[D]^d}{[A]^a[B]^b}\ \text{(تراكيز لحظية)}', 1, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('aec4afea-1d79-5eaa-9def-33eff0b6e483', '43704526-882c-5335-b251-9984e7c529b3', 'حاصل التفاعل Q هو:', 'Q تساوي Kc فقط عندما يكون النظام في حالة اتزان، وإلا فهي تتغير مع الزمن.', 1, 'editorial'),
 ('b0295ffe-3d9f-5c9f-8e32-bd255f26fb42', '43704526-882c-5335-b251-9984e7c529b3', 'إذا كانت Q < Kc فإن التفاعل:', 'النواتج أقل من الكمية عند الاتزان فيسير التفاعل نحو تكوين المزيد منها.', 1, 'editorial'),
 ('cc185e52-594f-5c36-b449-6817472398b2', '43704526-882c-5335-b251-9984e7c529b3', 'للتفاعل H₂ + I₂ ⇌ 2HI قيمة Kc = 50. في لحظة ما: [H₂] = 0.1 M و[I₂] = 0.1 M و[HI] = 0.5 M. ما اتجاه التفاعل؟', 'Q = (0.5)² / (0.1 × 0.1) = 0.25 / 0.01 = 25، وهي أقل من 50 فيسير التفاعل أماميًا.', 2, 'editorial'),
 ('8269bdc9-e0b9-5cdb-992a-e1e3c60c85b0', '43704526-882c-5335-b251-9984e7c529b3', 'للتفاعل نفسه (Kc = 50) كانت التراكيز: [H₂] = [I₂] = 0.1 M و[HI] = 1.0 M. ما اتجاه التفاعل؟', 'Q = (1.0)² / (0.1 × 0.1) = 1 / 0.01 = 100 > 50، فتزيد النواتج عن اللازم ويسير التفاعل عكسيًا.', 2, 'editorial'),
 ('36dd1b11-0f39-5dda-ae81-487498e8de02', '43704526-882c-5335-b251-9984e7c529b3', 'للتفاعل N₂O₄ ⇌ 2NO₂ كانت [NO₂] = 0.2 M و[N₂O₄] = 0.1 M في لحظة ما. ما قيمة Q؟', 'Q = [NO₂]² / [N₂O₄] = (0.2)² / 0.1 = 0.04 / 0.1 = 0.4.', 2, 'editorial'),
 ('070d4e59-2551-546c-bc21-a11d41e0bfde', '43704526-882c-5335-b251-9984e7c529b3', 'للتفاعل 2SO₂ + O₂ ⇌ 2SO₃ قيمة Kc = 36. إذا كانت [SO₃] = 0.6 M و[SO₂] = 0.1 M و[O₂] = 0.1 M فإن:', 'Q = (0.6)² / ((0.1)² × 0.1) = 0.36 / 0.001 = 360 > 36، فيسير التفاعل عكسيًا ويتحلل SO₃.', 3, 'editorial');
INSERT INTO question_options (id, question_id, label_ar, is_correct, sort_order) VALUES
