 ('72c1ae70-55e9-5637-9d23-4df68fd7a9e8', 'cc185e52-594f-5c36-b449-6817472398b2', 'النظام في اتزان', 0, 2),
 ('1312ef12-7e83-53c6-8833-fab1297c3a8a', 'cc185e52-594f-5c36-b449-6817472398b2', 'أمامي لأن Q = 25 أقل من Kc', 1, 3),
 ('4aeaac20-6762-5efe-91e5-f933b5d1dade', 'cc185e52-594f-5c36-b449-6817472398b2', 'أمامي لأن Q = 50', 0, 4),
