 ('166a3946-c832-5e42-b650-e8bdda3b3f1f', '8269bdc9-e0b9-5cdb-992a-e1e3c60c85b0', 'النظام في اتزان', 0, 3),
 ('3f04dac8-2da7-5650-9e2b-c64536a2eb53', '8269bdc9-e0b9-5cdb-992a-e1e3c60c85b0', 'عكسي لأن Q = 10', 0, 4),
 ('a3d14078-de11-5792-870b-f3a6c9c571c5', '36dd1b11-0f39-5dda-ae81-487498e8de02', '0.4', 1, 1),
