 ('7d8a06e1-c485-519c-a129-4cddab105e2d', '36dd1b11-0f39-5dda-ae81-487498e8de02', '2', 0, 3),
 ('ec536ac6-16c8-5996-86e7-fef2de7b3e39', '36dd1b11-0f39-5dda-ae81-487498e8de02', '0.04', 0, 4),
 ('16d5421d-9706-5f59-b3ef-f83d252a5cc7', '070d4e59-2551-546c-bc21-a11d41e0bfde', 'التفاعل يسير أماميًا فيزداد تركيز SO₃', 0, 1),
 ('dc986f00-51b3-5dcb-aaa0-64b53e04f8e3', '070d4e59-2551-546c-bc21-a11d41e0bfde', 'النظام في حالة اتزان', 0, 2),
 ('1522f290-cd4e-532a-b6c5-70d9145461dd', '070d4e59-2551-546c-bc21-a11d41e0bfde', 'لا يمكن تحديد الاتجاه', 0, 3),
 ('ee14ab7f-2afe-5b95-a3cb-d557beaafe03', '070d4e59-2551-546c-bc21-a11d41e0bfde', 'التفاعل يسير عكسيًا فيزداد تركيز SO₂', 1, 4);
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('19b138e6-d67d-5251-9449-66d4489302b4', 'a7c6822d-2cbd-53ed-8890-17f4a112fe0d', 'ثابت الاتزان Kp والعلاقة بينه وبين Kc', 'في الأنظمة الغازية يعبر Kp عن الاتزان بالضغوط الجزئية للغازات (المواد الصلبة والسائلة لا تُكتب). العلاقة بين الثابتين Kp = Kc (RT)^Δn حيث Δn هو الفرق بين مجموع معاملات النواتج الغازية ومجموع معاملات المتفاعلات الغازية. الضغط الجزئي = الكسر المولي × الضغط الكلي.', 'K_p = \dfrac{P_{NH_3}^2}{P_{N_2}\,P_{H_2}^3}', 2, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('9b31af2d-989f-535f-b62c-1880cf676da8', '19b138e6-d67d-5251-9449-66d4489302b4', 'يُكتب ثابت الاتزان Kp بدلالة:', 'Kp مخصص للتفاعلات الغازية ويعتمد على الضغوط الجزئية للغازات.', 1, 'editorial'),
 ('d932575b-257f-5ed7-8a60-67139fe57135', '19b138e6-d67d-5251-9449-66d4489302b4', 'تعبير Kp للتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) هو:', 'النواتج في البسط والمتفاعلات في المقام وكل ضغط مرفوع إلى معامله.', 1, 'editorial'),
 ('d90da5d7-718d-51ab-9b5f-46baf7ed0ae8', '19b138e6-d67d-5251-9449-66d4489302b4', 'قيمة Δn للتفاعل N₂(g) + 3H₂(g) ⇌ 2NH₃(g) هي:', 'Δn = 2 - (1 + 3) = 2 - 4 = -2.', 2, 'editorial'),
 ('1f3bb330-596d-5b56-9a29-5e2e9610f568', '19b138e6-d67d-5251-9449-66d4489302b4', 'أي التفاعلات الآتية تتساوى فيه قيمتا Kp وKc؟', 'في تفاعل HI: Δn = 2 - 2 = 0 فيكون (RT)⁰ = 1 وتتساوى Kp وKc.', 2, 'editorial'),
 ('1a4d6541-5ee8-5e4e-a2b5-f4e6f905cdc7', '19b138e6-d67d-5251-9449-66d4489302b4', 'عند الاتزان للتفاعل N₂ + 3H₂ ⇌ 2NH₃ كانت الضغوط الجزئية: P(N₂) = 1 atm و P(H₂) = 2 atm و P(NH₃) = 4 atm. ما قيمة Kp؟', 'Kp = (4)² / (1 × 2³) = 16 / 8 = 2 (وحدتها atm⁻²).', 3, 'editorial'),
 ('240acc9f-e729-50f4-8eb9-259508bac01f', '19b138e6-d67d-5251-9449-66d4489302b4', 'خليط من N₂O₄ و NO₂ عند الاتزان N₂O₄ ⇌ 2NO₂ ضغطه الكلي 10 atm ويحتوي على 2 mol N₂O₄ و3 mol NO₂. ما قيمة Kp؟', 'الكسور المولية: N₂O₄ = 2/5 فالضغط 4 atm، NO₂ = 3/5 فالضغط 6 atm. Kp = (6)² / 4 = 36 / 4 = 9 atm.', 3, 'editorial');
INSERT INTO question_options (id, question_id, label_ar, is_correct, sort_order) VALUES
 ('fa1ac0a1-41ed-50f1-810a-30dcdeb180c5', '9b31af2d-989f-535f-b62c-1880cf676da8', 'التراكيز المولارية لجميع المواد', 0, 1),
 ('b2512755-6fa7-504e-937b-53f08957ce51', '9b31af2d-989f-535f-b62c-1880cf676da8', 'درجة حرارة النظام فقط', 0, 2),
 ('8b76fa43-9d3a-50f4-aac9-78c3c4b22feb', '9b31af2d-989f-535f-b62c-1880cf676da8', 'الضغوط الجزئية للمواد الغازية', 1, 3),
 ('45ed760e-03f5-5e35-9f59-10116be34e61', '9b31af2d-989f-535f-b62c-1880cf676da8', 'عدد مولات المواد الصلبة', 0, 4),
 ('87ae11b2-4618-591b-9da3-7d0e74cd19a1', 'd932575b-257f-5ed7-8a60-67139fe57135', 'Kp = P(N₂) × P(H₂)³ / P(NH₃)²', 0, 1),
 ('f0541853-b551-58b9-a2ce-b982cf5b74b5', 'd932575b-257f-5ed7-8a60-67139fe57135', 'Kp = P(NH₃)² / (P(N₂) × P(H₂)³)', 1, 2),
 ('6dcb8103-f55d-5112-9e63-c285ca7ef351', 'd932575b-257f-5ed7-8a60-67139fe57135', 'Kp = P(NH₃) / (P(N₂) × P(H₂))', 0, 3),
 ('3d899fe3-4caf-5f6d-8d5e-a73ffb4187e4', 'd932575b-257f-5ed7-8a60-67139fe57135', 'Kp = 2P(NH₃) / (P(N₂) + 3P(H₂))', 0, 4),
 ('0d9118e5-a0d6-518b-b917-0d966b813aed', 'd90da5d7-718d-51ab-9b5f-46baf7ed0ae8', '-2', 1, 1),
 ('fece2ab2-3d98-5dc6-b334-9759b7ea203b', 'd90da5d7-718d-51ab-9b5f-46baf7ed0ae8', '+2', 0, 2),
 ('d08e6faa-ca9a-5607-b0c1-d65ea5e15838', 'd90da5d7-718d-51ab-9b5f-46baf7ed0ae8', '-1', 0, 3),
 ('0f4b3a24-3bf4-5b96-b30e-4b2459c1bd87', 'd90da5d7-718d-51ab-9b5f-46baf7ed0ae8', 'صفر', 0, 4),
 ('9746bc4a-dd00-5094-9623-3a214d6d5fc7', '1f3bb330-596d-5b56-9a29-5e2e9610f568', 'N₂(g) + 3H₂(g) ⇌ 2NH₃(g)', 0, 1),
 ('b7cb379a-ea4e-594a-b183-ed3b961f1f6c', '1f3bb330-596d-5b56-9a29-5e2e9610f568', 'PCl₅(g) ⇌ PCl₃(g) + Cl₂(g)', 0, 2),
 ('77d06db0-bed5-5bca-bc32-9e592516e40c', '1f3bb330-596d-5b56-9a29-5e2e9610f568', '2SO₂(g) + O₂(g) ⇌ 2SO₃(g)', 0, 3),
 ('75443e25-dd6c-5951-b901-0635d7bec5f2', '1f3bb330-596d-5b56-9a29-5e2e9610f568', 'H₂(g) + I₂(g) ⇌ 2HI(g)', 1, 4),
 ('3a4d02fd-ab89-599a-aae5-6076a05367a0', '1a4d6541-5ee8-5e4e-a2b5-f4e6f905cdc7', '4 atm⁻²', 0, 1),
 ('2a4fcf19-2163-570a-909c-3a0c63b73b29', '1a4d6541-5ee8-5e4e-a2b5-f4e6f905cdc7', '8 atm⁻²', 0, 2),
 ('a102979d-5f41-5285-838d-9d4013915730', '1a4d6541-5ee8-5e4e-a2b5-f4e6f905cdc7', '2 atm⁻²', 1, 3),
 ('8807f7bd-4b15-552d-8800-3c7cf17cdda2', '1a4d6541-5ee8-5e4e-a2b5-f4e6f905cdc7', '0.5 atm⁻²', 0, 4),
 ('0d966793-caee-58d7-abe5-d0d7e9e44170', '240acc9f-e729-50f4-8eb9-259508bac01f', '6 atm', 0, 1),
 ('faee7158-04a0-56ea-b83d-9834145a4d44', '240acc9f-e729-50f4-8eb9-259508bac01f', '9 atm', 1, 2),
 ('dc7131ef-6a91-5323-a779-35a958a0fb08', '240acc9f-e729-50f4-8eb9-259508bac01f', '2.25 atm', 0, 3),
 ('081cc214-6cc1-510f-b43e-835e24e2f440', '240acc9f-e729-50f4-8eb9-259508bac01f', '1.5 atm', 0, 4);
INSERT INTO units (id, course_id, title_ar, summary_ar, sort_order, origin, source_id) VALUES ('19220430-78a8-5d6e-9989-8a4dca9ca3a4', '00000000-0000-0000-0000-000000000b02', 'الأحماض والقواعد', 'نظريتا أرهينيوس وبرونستد-لوري، والأزواج المترافقة، وثابت تأين الماء Kw وحساب pH، وقوة الأحماض والقواعد بالثوابت Ka وKb، والتعادل والمعايرة وتميؤ الأملاح.', 2, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) VALUES ('c0d9523e-1b6c-5646-83f3-e1841f6521a3', '19220430-78a8-5d6e-9989-8a4dca9ca3a4', 'نظريات الأحماض والقواعد والأزواج المترافقة', 'نقارن بين تعريف أرهينيوس وتعريف برونستد-لوري للحمض والقاعدة، ونتعلم تحديد الأزواج المترافقة (حمض - قاعدة).', '["تعريف الحمض والقاعدة وفق أرهينيوس وبرونستد-لوري","تحديد الحمض والقاعدة في تفاعل انتقال البروتون","كتابة القاعدة المرافقة للحمض والحمض المرافق للقاعدة"]', '[{"type":"text","text":"عرّف أرهينيوس الحمض بأنه مادة تعطي أيونات الهيدروجين H⁺ (تُكتب غالبًا H₃O⁺) عند ذوبانها في الماء، والقاعدة بأنها مادة تعطي أيونات الهيدروكسيد OH⁻. وتقتصر هذه النظرية على المحاليل المائية، ولا تفسر قاعدية النشادر NH₃ لأنه لا يحتوي على مجموعة OH⁻."},{"type":"text","text":"عرّف برونستد ولوري الحمض بأنه مادة مانحة للبروتون (H⁺)، والقاعدة بأنها مادة مستقبلة للبروتون. وبهذا يمكن تفسير سلوك NH₃ كقاعدة، كما تنطبق النظرية على تفاعلات خارج الماء."},{"type":"formula","tex":"NH_3 + H_2O \\rightleftharpoons NH_4^+ + OH^-"},{"type":"text","text":"في هذا التفاعل يستقبل NH₃ بروتونًا من الماء فهو قاعدة، ويمنح الماء بروتونًا فهو حمض. كل حمض يفقد بروتونًا ينتج قاعدة مرافقة، وكل قاعدة تكتسب بروتونًا تنتج حمضًا مرافقًا، ويسمى الاثنان زوجًا مترافقًا يختلفان بروتونًا واحدًا فقط."},{"type":"formula","tex":"HA + H_2O \\rightleftharpoons H_3O^+ + A^-"},{"type":"note","text":"المواد الأمفوتيرية (مثل H₂O وHCO₃⁻) تسلك كحمض في تفاعل وكقاعدة في تفاعل آخر. وكلما كان الحمض أقوى كانت قاعدته المرافقة أضعف، والعكس صحيح."}]', 1, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('901e536c-d6c8-52da-b34d-4f8069f81329', 'c0d9523e-1b6c-5646-83f3-e1841f6521a3', 'نظريتا أرهينيوس وبرونستد-لوري', 'الحمض عند أرهينيوس يعطي H⁺ في الماء والقاعدة تعطي OH⁻. أما عند برونستد-لوري فالحمض مانح للبروتون والقاعدة مستقبلة له، وهذا التعريف أشمل لأنه يفسر قاعدية مواد مثل NH₃ ولا يشترط وجود OH⁻ ولا الماء. الماء يسلك كحمض أو كقاعدة حسب المادة التي يتفاعل معها.', '\text{حمض} \rightarrow \text{قاعدة} + H^+', 1, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('aa7c6a33-92d5-5712-9e57-b5dffcf703cc', '901e536c-d6c8-52da-b34d-4f8069f81329', 'الحمض حسب تعريف أرهينيوس هو مادة:', 'تعريف أرهينيوس للحمض مرتبط بإعطاء أيون الهيدروجين في المحلول المائي.', 1, 'editorial'),
 ('608415b3-bf26-51c7-8f0a-b69bb8048180', '901e536c-d6c8-52da-b34d-4f8069f81329', 'الحمض حسب تعريف برونستد-لوري هو:', 'الحمض يمنح البروتون H⁺ لمادة أخرى.', 1, 'editorial'),
 ('32fce495-4103-5df6-b669-92a102a77514', '901e536c-d6c8-52da-b34d-4f8069f81329', 'القاعدة حسب تعريف برونستد-لوري هي:', 'القاعدة تأخذ البروتون من الحمض.', 1, 'editorial'),
 ('a96d0a04-a55d-571e-8a75-c723dc0ecbfa', '901e536c-d6c8-52da-b34d-4f8069f81329', 'في التفاعل NH₃ + H₂O ⇌ NH₄⁺ + OH⁻ يسلك الماء سلوك:', 'يفقد H₂O بروتونًا ليصبح OH⁻ فهو حمض برونستد في هذا التفاعل.', 2, 'editorial'),
 ('140f5f22-19ff-5298-b509-633f466924a8', '901e536c-d6c8-52da-b34d-4f8069f81329', 'أي الظواهر الآتية لا تفسرها نظرية أرهينيوس وتفسرها نظرية برونستد-لوري؟', 'NH₃ قاعدة لا تحتوي على OH⁻، لكنها تستقبل بروتونًا فهي قاعدة برونستد.', 2, 'editorial'),
 ('d5890d53-c0d6-54e8-a2d0-32f366ebd105', '901e536c-d6c8-52da-b34d-4f8069f81329', 'أي الأنواع الآتية يمكن أن يسلك كحمض وكقاعدة حسب برونستد-لوري؟', 'HCO₃⁻ يستطيع منح بروتون ليصبح CO₃²⁻ أو استقبال بروتون ليصبح H₂CO₃، فهو أمفوتيري.', 2, 'editorial');
INSERT INTO question_options (id, question_id, label_ar, is_correct, sort_order) VALUES
 ('901152fd-f093-5fb8-92b5-2d50537cfa56', 'aa7c6a33-92d5-5712-9e57-b5dffcf703cc', 'تعطي أيونات H⁺ عند ذوبانها في الماء', 1, 1),
