 ('30cd9ce8-2832-5831-900c-ff8506be4648', '32fce495-4103-5df6-b669-92a102a77514', 'مادة مانحة للبروتون', 0, 1),
 ('db7f239b-74d1-57d0-9778-cf0bdc4c3520', '32fce495-4103-5df6-b669-92a102a77514', 'مادة لا تحتوي على الهيدروجين', 0, 2),
 ('01697982-a91d-5694-8dd5-959de7f594ad', '32fce495-4103-5df6-b669-92a102a77514', 'مادة مستقبلة للبروتون', 1, 3),
