INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('3340c096-aad0-55fa-8a48-45f549c41712', 'c0d9523e-1b6c-5646-83f3-e1841f6521a3', 'الأزواج المترافقة (حمض - قاعدة)', 'القاعدة المرافقة لحمض = الحمض - H⁺، والحمض المرافق لقاعدة = القاعدة + H⁺. يتكون الزوج المترافق من نوعين يختلفان بروتونًا واحدًا فقط. علاقة القوة عكسية: الحمض القوي له قاعدة مرافقة ضعيفة جدًا، والحمض الضعيف له قاعدة مرافقة أقوى نسبيًا.', 'HA \rightleftharpoons H^+ + A^-', 2, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('bd192b7f-b721-5fb0-9722-f5370ee83c77', '3340c096-aad0-55fa-8a48-45f549c41712', 'القاعدة المرافقة للحمض HCl هي:', 'بفقدان البروتون: HCl - H⁺ = Cl⁻.', 1, 'editorial'),
 ('24dde660-edeb-5066-8944-ac84a05ddc7e', '3340c096-aad0-55fa-8a48-45f549c41712', 'الحمض المرافق للقاعدة NH₃ هو:', 'باكتساب البروتون: NH₃ + H⁺ = NH₄⁺.', 1, 'editorial'),
 ('12db678e-7578-580a-b521-d8b2fa2fafc5', '3340c096-aad0-55fa-8a48-45f549c41712', 'الحمض المرافق للماء H₂O هو:', 'H₂O + H⁺ = H₃O⁺.', 1, 'editorial'),
 ('36ddefeb-fe7b-5c88-9d4e-8a2d7e936641', '3340c096-aad0-55fa-8a48-45f549c41712', 'القاعدة المرافقة للحمض H₂SO₄ هي:', 'فقد H₂SO₄ بروتونًا واحدًا فصار HSO₄⁻.', 2, 'editorial'),
 ('a059d34d-9b99-53e0-9f84-f6bf354b514a', '3340c096-aad0-55fa-8a48-45f549c41712', 'في التفاعل HF + H₂O ⇌ F⁻ + H₃O⁺ أي الأزواج الآتية زوج مترافق؟', 'HF و F⁻ يختلفان بروتونًا واحدًا، كذلك H₂O و H₃O⁺.', 2, 'editorial'),
 ('ef22d0a7-bfb3-5bd3-b68c-f8235b23f667', '3340c096-aad0-55fa-8a48-45f549c41712', 'أي الأحماض الآتية له أضعف قاعدة مرافقة؟', 'HCl أقوى هذه الأحماض، فقاعدته المرافقة Cl⁻ هي الأضعف.', 3, 'editorial');
INSERT INTO question_options (id, question_id, label_ar, is_correct, sort_order) VALUES
