INSERT INTO lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) VALUES ('3861afa1-a826-554a-88de-682ed06db10b', '19220430-78a8-5d6e-9989-8a4dca9ca3a4', 'تأين الماء Kw والأس الهيدروجيني', 'نفهم التأين الذاتي للماء وثابته Kw، ونستخدم مقياس pH وpOH للتعبير عن حمضية المحاليل وقاعديتها.', '["كتابة ثابت تأين الماء Kw وقيمته عند 25 °C","حساب [H₃O⁺] و[OH⁻] وإحدى القيمتين بدلالة الأخرى","حساب pH وpOH للمحاليل ومعرفة نوع المحلول"]', '[{"type":"text","text":"الماء النقي يتأين بدرجة ضئيلة جدًا: جزيء ماء يمنح بروتونًا لجزيء ماء آخر. وهذا يسمى التأين الذاتي للماء."},{"type":"formula","tex":"2H_2O \\rightleftharpoons H_3O^+ + OH^-"},{"type":"formula","tex":"K_w = [H_3O^+][OH^-] = 1\\times10^{-14}\\ \\ (25^\\circ C)"},{"type":"text","text":"في الماء النقي عند 25 °C يكون [H₃O⁺] = [OH⁻] = 1 × 10⁻⁷ M. ويزداد Kw بارتفاع درجة الحرارة لأن التأين ماص للحرارة. في المحاليل المائية يبقى حاصل ضرب التركيزين ثابتًا، فإذا زاد أحدهما قل الآخر."},{"type":"text","text":"لتسهيل التعامل مع هذه الأرقام الصغيرة نستخدم مقياس pH:"},{"type":"formula","tex":"pH = -\\log[H_3O^+] \\qquad pOH = -\\log[OH^-] \\qquad pH + pOH = 14"},{"type":"note","text":"عند 25 °C: المحلول المتعادل pH = 7، والحمضي pH < 7، والقاعدي pH > 7. نقص pH بمقدار وحدة واحدة يعني زيادة [H₃O⁺] عشرة أمثال."}]', 2, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('b82e0b7d-b89a-529b-a4ec-b66fc8521b79', '3861afa1-a826-554a-88de-682ed06db10b', 'ثابت تأين الماء Kw', 'ثابت تأين الماء Kw = [H₃O⁺][OH⁻] وقيمته 1 × 10⁻¹⁴ عند 25 °C، ويتغير بتغير درجة الحرارة فقط. المحلول المتعادل هو الذي يتساوى فيه [H₃O⁺] و[OH⁻]، وفي المحلول الحمضي يكون [H₃O⁺] > [OH⁻]، وفي القاعدي يكون العكس. يمكن حساب أحد التركيزين إذا عُلم الآخر.', 'K_w = [H_3O^+][OH^-] = 10^{-14}', 1, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('d57b7399-8281-5f25-a71a-df268e4f01b1', 'b82e0b7d-b89a-529b-a4ec-b66fc8521b79', 'قيمة ثابت تأين الماء Kw عند 25 °C هي:', 'Kw = [H₃O⁺][OH⁻] = 10⁻⁷ × 10⁻⁷ = 10⁻¹⁴.', 1, 'editorial'),
 ('7a460217-c83b-5ffd-a3d3-3d2a859318c6', 'b82e0b7d-b89a-529b-a4ec-b66fc8521b79', 'تركيز أيون الهيدرونيوم في الماء النقي عند 25 °C يساوي:', 'الماء النقي متعادل ويتساوى فيه [H₃O⁺] و[OH⁻] وكل منهما 10⁻⁷ M.', 1, 'editorial'),
 ('1e5fb100-60d4-5bbd-a845-85972884e637', 'b82e0b7d-b89a-529b-a4ec-b66fc8521b79', 'محلول تركيز H₃O⁺ فيه 1 × 10⁻³ M عند 25 °C. ما تركيز OH⁻؟', '[OH⁻] = Kw / [H₃O⁺] = 10⁻¹⁴ / 10⁻³ = 10⁻¹¹ M.', 2, 'editorial'),
 ('e69a2d03-916a-56c6-944f-9c620eb811e6', 'b82e0b7d-b89a-529b-a4ec-b66fc8521b79', 'عند ارتفاع درجة الحرارة فإن قيمة Kw:', 'رفع الحرارة يزيح اتزان تأين الماء نحو الأيونات، فيزداد Kw.', 2, 'editorial'),
 ('6e3908a3-c561-5dc4-a723-6a07e031a589', 'b82e0b7d-b89a-529b-a4ec-b66fc8521b79', 'محلول تركيز H₃O⁺ فيه 4 × 10⁻³ M عند 25 °C. ما تركيز OH⁻؟', '[OH⁻] = 10⁻¹⁴ / (4 × 10⁻³) = 0.25 × 10⁻¹¹ = 2.5 × 10⁻¹² M.', 3, 'editorial'),
 ('6671c327-999a-56ca-a179-491dd5a54756', 'b82e0b7d-b89a-529b-a4ec-b66fc8521b79', 'عند 60 °C يكون pH الماء النقي أقل من 7. هذا يعني أن الماء عند هذه الدرجة:', 'ارتفاع Kw يرفع [H₃O⁺] فيقل pH، لكن التعادل يعني تساوي [H₃O⁺] و[OH⁻] وهو متحقق.', 3, 'editorial');
