 ('fa0918e8-1f52-573f-872e-fa63d1818baf', '6671c327-999a-56ca-a179-491dd5a54756', 'أصبح حمضيًا لأن [H₃O⁺] > [OH⁻]', 0, 1),
 ('e6b50f5c-f4ce-5260-b3cc-4b33599f2d77', '6671c327-999a-56ca-a179-491dd5a54756', 'أصبح قاعديًا', 0, 2),
