 ('a7d3c514-7870-5909-9dbd-7f38a497d822', '6671c327-999a-56ca-a179-491dd5a54756', 'ما زال متعادلًا لأن [H₃O⁺] = [OH⁻]', 1, 4);
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('d0c09f4b-402e-5078-8cc9-87bda8d8602b', '3861afa1-a826-554a-88de-682ed06db10b', 'الأس الهيدروجيني pH وpOH', 'الأس الهيدروجيني pH = -log[H₃O⁺] و pOH = -log[OH⁻]، ومجموعهما 14 عند 25 °C. كلما قل pH زادت حمضية المحلول. تغير pH بمقدار وحدة واحدة يقابله تغير [H₃O⁺] عشرة أمثال. في الحسابات نفترض أن الحمض القوي يتأين تمامًا وأن المقدار [H₃O⁺] = N × M للحمض ذي N من الهيدروجينات الحمضية القوية.', 'pH = -\log[H_3O^+]', 2, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('cf6b8bc5-acf4-5061-b9f8-5be962849119', 'd0c09f4b-402e-5078-8cc9-87bda8d8602b', 'العلاقة التي تعرّف الأس الهيدروجيني هي:', 'pH هو اللوغاريتم العشري السالب لتركيز أيون الهيدرونيوم.', 1, 'editorial'),
 ('2f9fb535-3bf8-5d55-9d94-91c642ef4459', 'd0c09f4b-402e-5078-8cc9-87bda8d8602b', 'محلول [H₃O⁺] فيه = 1 × 10⁻³ M. ما قيمة pH؟', 'pH = -log(10⁻³) = 3.', 1, 'editorial'),
 ('ce4c95d4-c616-58cb-a2fa-17283a4d35f4', 'd0c09f4b-402e-5078-8cc9-87bda8d8602b', 'إذا كان pOH لمحلول = 4 عند 25 °C فإن pH يساوي:', 'pH = 14 - pOH = 14 - 4 = 10.', 1, 'editorial'),
 ('f04cbcac-84be-50ac-a333-b3ea952148fc', 'd0c09f4b-402e-5078-8cc9-87bda8d8602b', 'محلول [OH⁻] فيه = 1 × 10⁻² M عند 25 °C. ما قيمة pH؟', 'pOH = 2 فيكون pH = 14 - 2 = 12.', 2, 'editorial'),
 ('be82fc38-caa1-56af-8df4-291162cf57b5', 'd0c09f4b-402e-5078-8cc9-87bda8d8602b', 'محلولان: الأول pH = 3 والثاني pH = 5. تركيز H₃O⁺ في الثاني يساوي:', 'الفرق وحدتان في pH يعني فرق 10² = 100 مرة، والمحلول الأعلى pH أقل حمضية.', 2, 'editorial'),
 ('ac899662-9d4a-58b1-91ec-1a429c969d47', 'd0c09f4b-402e-5078-8cc9-87bda8d8602b', 'ما قيمة pH لمحلول [H₃O⁺] فيه = 2 × 10⁻³ M؟ (log 2 = 0.3)', 'pH = -log(2 × 10⁻³) = 3 - log 2 = 3 - 0.3 = 2.7.', 3, 'editorial'),
 ('b07ef42a-3ca8-5eed-87e1-4ab52f40a174', 'd0c09f4b-402e-5078-8cc9-87bda8d8602b', 'ما قيمة pH لمحلول حمض الكبريتيك H₂SO₄ تركيزه 0.0005 M؟ (افترض التأين التام للهيدروجينين)', '[H₃O⁺] = 2 × 0.0005 = 0.001 = 10⁻³ M، إذن pH = 3.', 3, 'editorial');
