INSERT INTO lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) VALUES ('211a1eb0-8f88-5487-ab99-d3035e36293e', '19220430-78a8-5d6e-9989-8a4dca9ca3a4', 'قوة الأحماض والقواعد وثوابت التأين', 'نفرّق بين الحمض أو القاعدة القوية والضعيفة، ونستخدم Ka وKb لحساب pH ودرجة التأين لمحلول ضعيف.', '["التمييز بين الأحماض والقواعد القوية والضعيفة","كتابة تعبيري Ka وKb واستخدام العلاقة Ka × Kb = Kw","حساب pH ودرجة التأين لحمض أو قاعدة ضعيفة"]', '[{"type":"text","text":"الحمض القوي مثل HCl وHNO₃ يتأين تقريبًا تمامًا في الماء، والقاعدة القوية مثل NaOH وKOH تتفكك تمامًا. أما الحمض الضعيف مثل CH₃COOH فيتأين جزئيًا ويصل إلى اتزان بين الجزيئات والأيونات."},{"type":"formula","tex":"CH_3COOH + H_2O \\rightleftharpoons H_3O^+ + CH_3COO^- \\qquad K_a = \\dfrac{[H_3O^+][CH_3COO^-]}{[CH_3COOH]}"},{"type":"text","text":"كلما كبرت Ka كان الحمض أقوى. وبالمثل Kb للقواعد الضعيفة، مثل NH₃ التي يكون لها Kb = [NH₄⁺][OH⁻] / [NH₃]. وللزوج المترافق تتحقق العلاقة Ka × Kb = Kw."},{"type":"text","text":"لحمض ضعيف أحادي البروتون بتركيز C وثابت Ka صغير (التأين أقل من 5% تقريبًا) نهمل التغير في تركيز الحمض فنحصل على:"},{"type":"formula","tex":"[H_3O^+] = \\sqrt{K_a \\times C} \\qquad \\alpha = \\sqrt{\\dfrac{K_a}{C}}"},{"type":"note","text":"القوة (درجة التأين) غير التركيز: يمكن أن يكون محلول حمض ضعيف مركزًا ومحلول حمض قوي مخففًا. وعند تخفيف حمض ضعيف تزداد درجة التأين α بينما تبقى Ka ثابتة عند ثبوت درجة الحرارة."}]', 3, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('6d6ebad6-82e5-5e66-83b6-593fc1e15856', '211a1eb0-8f88-5487-ab99-d3035e36293e', 'قوة الأحماض والقواعد وثوابت Ka وKb', 'الحمض القوي يتأين كليًا، والضعيف جزئيًا. ثابت تأين الحمض Ka يقيس قوته: كلما زادت Ka زادت القوة. للقواعد الضعيفة Kb، وللزوج المترافق Ka × Kb = Kw. لا يظهر الماء في تعبيري Ka وKb لأنه سائل نقي. محلول الحمض القوي يوصل الكهرباء أفضل من محلول حمض ضعيف بالتركيز نفسه لأن تركيز الأيونات فيه أكبر.', 'K_a \times K_b = K_w', 1, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('8909a473-b117-5ca6-b519-32f307933991', '6d6ebad6-82e5-5e66-83b6-593fc1e15856', 'أي الأحماض الآتية حمض قوي؟', 'حمض النيتريك من الأحماض المعدنية القوية التي تتأين تامًا في الماء.', 1, 'editorial'),
 ('4bac0f8e-c877-5a87-a835-4421ba49aca2', '6d6ebad6-82e5-5e66-83b6-593fc1e15856', 'ثابت التأين Ka للحمض CH₃COOH يُكتب على الصورة:', 'النواتج في البسط والحمض غير المتأين في المقام، ولا يظهر الماء.', 1, 'editorial'),
 ('ca005974-aef7-5340-a125-f88944f81ef0', '6d6ebad6-82e5-5e66-83b6-593fc1e15856', 'أربعة أحماض أحادية البروتون ثوابت تأينها: HA = 3 × 10⁻⁵ و HB = 2 × 10⁻⁴ و HC = 5 × 10⁻¹⁰ و HD = 7 × 10⁻⁸. أقواها هو:', 'الحمض الأقوى هو صاحب أكبر قيمة Ka، وهي 2 × 10⁻⁴.', 2, 'editorial'),
 ('3acbfabb-edb9-5c2c-b903-1741d18821c5', '6d6ebad6-82e5-5e66-83b6-593fc1e15856', 'أي القواعد الآتية قاعدة ضعيفة؟', 'النشادر يتأين جزئيًا في الماء، أما الهيدروكسيدات المذكورة فتتفكك تمامًا.', 2, 'editorial'),
 ('4b7657ea-82b6-56c6-b468-c5628281b75c', '6d6ebad6-82e5-5e66-83b6-593fc1e15856', 'تعبير Kb للتفاعل NH₃ + H₂O ⇌ NH₄⁺ + OH⁻ هو:', 'لا يظهر الماء لأنه سائل نقي ويدخل تركيزه في قيمة Kb.', 2, 'editorial'),
 ('a3852fcb-0c5c-56ac-92b2-5bfc61f41169', '6d6ebad6-82e5-5e66-83b6-593fc1e15856', 'إذا كانت Kb للنشادر = 1.8 × 10⁻⁵ فما قيمة Ka للأمونيوم NH₄⁺ عند 25 °C؟', 'Ka = Kw / Kb = 10⁻¹⁴ / (1.8 × 10⁻⁵) ≈ 5.6 × 10⁻¹⁰.', 3, 'editorial'),
 ('9f0b05cb-9525-5812-b43d-1339bd69d6d1', '6d6ebad6-82e5-5e66-83b6-593fc1e15856', 'محلولان 0.1 M من HCl و0.1 M من CH₃COOH. أيهما أعلى توصيلًا للكهرباء ولماذا؟', 'التوصيل يعتمد على تركيز الأيونات، وHCl حمض قوي يتأين كليًا بينما CH₃COOH يتأين جزئيًا.', 3, 'editorial');
INSERT INTO question_options (id, question_id, label_ar, is_correct, sort_order) VALUES
