 ('80996857-c8fe-5e45-a0d9-45d16a9cad0b', '4bac0f8e-c877-5a87-a835-4421ba49aca2', 'Ka = [H₃O⁺][CH₃COO⁻] / [H₂O]', 0, 2),
 ('6be67dc2-f0b6-5180-8e23-6ad1913983fc', '4bac0f8e-c877-5a87-a835-4421ba49aca2', 'Ka = [H₃O⁺][CH₃COO⁻] / [CH₃COOH]', 1, 3),
 ('216b2d5c-5d60-59c6-bdcc-85d1272d71af', '4bac0f8e-c877-5a87-a835-4421ba49aca2', 'Ka = [H₃O⁺] + [CH₃COO⁻]', 0, 4),
