 ('50b2d0f0-be43-5025-9688-1d99ba1def6f', 'a3852fcb-0c5c-56ac-92b2-5bfc61f41169', '5.6 × 10⁻⁵', 0, 2),
 ('b7b37026-f07d-51dd-8e05-ff8ec2445310', 'a3852fcb-0c5c-56ac-92b2-5bfc61f41169', '5.6 × 10⁻¹⁰', 1, 3),
 ('8595a74d-ab1c-5b72-a55e-bb78729d1c7c', 'a3852fcb-0c5c-56ac-92b2-5bfc61f41169', '1.8 × 10⁻¹⁹', 0, 4),
 ('35e65e6d-d68f-59a5-8c37-b0ec7717f76e', '9f0b05cb-9525-5812-b43d-1339bd69d6d1', 'CH₃COOH لأنه يتأين تامًا', 0, 1),
 ('08bef63e-b0e2-5b11-a1cb-52b7136877d4', '9f0b05cb-9525-5812-b43d-1339bd69d6d1', 'HCl لأن تركيز الأيونات فيه أكبر بسبب التأين التام', 1, 2),
 ('dc52b23c-940e-5682-b1d5-4055686ddab5', '9f0b05cb-9525-5812-b43d-1339bd69d6d1', 'متساويان لأن التركيز واحد', 0, 3),
 ('a740ba24-ff46-5b9d-881b-342075c39f28', '9f0b05cb-9525-5812-b43d-1339bd69d6d1', 'CH₃COOH لأن Ka له أكبر', 0, 4);
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('2f7cbbb7-9ac5-5f4b-8b57-8dc7b34f79a5', '211a1eb0-8f88-5487-ab99-d3035e36293e', 'حساب pH ودرجة التأين للحمض والقاعدة الضعيفة', 'لحمض ضعيف بتركيز C: [H₃O⁺] = √(Ka × C)، ودرجة التأين α = √(Ka / C). ولقاعدة ضعيفة: [OH⁻] = √(Kb × C). عند التخفيف تزداد درجة التأين وتبقى Ka ثابتة. ويمكن إيجاد Ka تجريبيًا من pH محلول معلوم التركيز: Ka = [H₃O⁺]² / C.', '[H_3O^+] = \sqrt{K_a\,C}', 2, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('2f265123-949b-5f69-b528-bdbd401b3374', '2f7cbbb7-9ac5-5f4b-8b57-8dc7b34f79a5', 'القانون التقريبي لحساب [H₃O⁺] لمحلول حمض ضعيف أحادي البروتون تركيزه C هو:', 'عندما يكون التأين ضئيلًا يكون [H₃O⁺]² = Ka × C.', 1, 'editorial'),
 ('f10fbc6a-2905-52b9-a910-4a1cf9c82ba8', '2f7cbbb7-9ac5-5f4b-8b57-8dc7b34f79a5', 'ما قيمة pH لمحلول حمض ضعيف أحادي البروتون تركيزه 0.1 M وثابت تأينه 1 × 10⁻⁵؟', '[H₃O⁺] = √(10⁻⁵ × 0.1) = √10⁻⁶ = 10⁻³ M فيكون pH = 3.', 2, 'editorial'),
 ('ec39ae73-8c89-538f-9810-6c39d6c2cf16', '2f7cbbb7-9ac5-5f4b-8b57-8dc7b34f79a5', 'ما درجة تأين حمض ضعيف تركيزه 0.1 M وثابت تأينه 1 × 10⁻⁵؟', 'α = √(Ka / C) = √(10⁻⁵ / 0.1) = √10⁻⁴ = 0.01 = 1%.', 2, 'editorial'),
 ('dded8016-81ce-56a5-b7aa-315d370eac3a', '2f7cbbb7-9ac5-5f4b-8b57-8dc7b34f79a5', 'عند تخفيف محلول حمض ضعيف بالماء عند درجة حرارة ثابتة:', 'α = √(Ka / C) فتزداد بنقص C، أما Ka فلا تتغير إلا بتغير درجة الحرارة.', 2, 'editorial'),
 ('03a8fcab-b473-5f39-a8a9-717ce3e466bd', '2f7cbbb7-9ac5-5f4b-8b57-8dc7b34f79a5', 'ما قيمة pH لمحلول حمض ضعيف أحادي البروتون تركيزه 0.2 M وثابت تأينه 2 × 10⁻⁵؟ (log 2 = 0.3)', '[H₃O⁺] = √(2 × 10⁻⁵ × 0.2) = √(4 × 10⁻⁶) = 2 × 10⁻³ فيكون pH = 3 - 0.3 = 2.7.', 3, 'editorial'),
 ('c95ee0d3-0670-5fe3-bfdc-f11f61ec5e40', '2f7cbbb7-9ac5-5f4b-8b57-8dc7b34f79a5', 'محلول حمض ضعيف أحادي البروتون تركيزه 0.1 M وقيمة pH له = 3. ما قيمة Ka؟', '[H₃O⁺] = 10⁻³ فتكون Ka = (10⁻³)² / 0.1 = 10⁻⁶ / 10⁻¹ = 10⁻⁵.', 3, 'editorial'),
 ('da1779f9-bf33-5661-a3e3-5d4b98438909', '2f7cbbb7-9ac5-5f4b-8b57-8dc7b34f79a5', 'ما قيمة pH لمحلول قاعدة ضعيفة تركيزه 0.01 M وثابت تأينها Kb = 1 × 10⁻⁶ عند 25 °C؟', '[OH⁻] = √(10⁻⁶ × 10⁻²) = 10⁻⁴ M فيكون pOH = 4 وبذلك pH = 14 - 4 = 10.', 3, 'editorial');
