INSERT INTO lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) VALUES ('9558ef81-c159-56ec-8f51-b431386a3ac4', '19220430-78a8-5d6e-9989-8a4dca9ca3a4', 'التعادل والمعايرة وتميؤ الأملاح', 'نتعلم تفاعل التعادل وحسابات المعايرة، ونفسر لماذا تعطي بعض الأملاح محاليل حمضية أو قاعدية.', '["كتابة معادلة التعادل وحساب حجم أو تركيز المحلول المجهول","اختيار الكاشف المناسب بحسب نوع الحمض والقاعدة","التنبؤ بنوع محلول الملح من الحمض والقاعدة المكونين له"]', '[{"type":"text","text":"التعادل هو تفاعل الحمض مع القاعدة لتكوين ملح وماء، والمعادلة الأيونية الأساسية لتعادل الحمض القوي مع القاعدة القوية هي:"},{"type":"formula","tex":"H^+ + OH^- \\rightarrow H_2O"},{"type":"text","text":"في المعايرة نضيف محلولًا معلوم التركيز (قياسي) من السحاحة إلى حجم معلوم من محلول مجهول التركيز حتى نقطة التكافؤ، وهي النقطة التي يتساوى عندها عدد مولات H⁺ مع عدد مولات OH⁻. ويُعرف الوصول إليها بتغير لون الكاشف."},{"type":"formula","tex":"\\dfrac{M_a V_a}{n_a} = \\dfrac{M_b V_b}{n_b}"},{"type":"text","text":"حيث n_a وn_b هما معاملا الحمض والقاعدة في معادلة التعادل الموزونة (مثلًا H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O فيها n_a = 1 وn_b = 2)."},{"type":"text","text":"pH عند نقطة التكافؤ يساوي 7 في معايرة حمض قوي بقاعدة قوية، ويكون أكبر من 7 عند معايرة حمض ضعيف بقاعدة قوية (فيستخدم الفينولفثالين)، وأقل من 7 عند معايرة قاعدة ضعيفة بحمض قوي."},{"type":"text","text":"تميؤ الملح هو تفاعل أيوناته مع الماء. أيونات الملح الناتجة من حمض قوي أو قاعدة قوية لا تتميأ، أما أيونات الحمض الضعيف (القاعدة المرافقة القوية نسبيًا) فتتميأ معطية OH⁻، وأيونات القاعدة الضعيفة (الحمض المرافق) تتميأ معطية H₃O⁺."},{"type":"formula","tex":"CH_3COO^- + H_2O \\rightleftharpoons CH_3COOH + OH^-"},{"type":"note","text":"ملح الحمض القوي والقاعدة القوية (مثل NaCl) متعادل. ملح حمض ضعيف وقاعدة قوية (مثل CH₃COONa) قاعدي. ملح حمض قوي وقاعدة ضعيفة (مثل NH₄Cl) حمضي."}]', 4, 'editorial', '49754f36-d43c-504f-af33-477e1206f9ea');
INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('7e2b03eb-1adb-5ffa-aaad-dde868c933d8', '9558ef81-c159-56ec-8f51-b431386a3ac4', 'التعادل والمعايرة', 'التعادل تفاعل حمض مع قاعدة ينتج ملحًا وماء. في المعايرة نستعمل العلاقة M_a × V_a / a = M_b × V_b / b حيث a وb معاملا الحمض والقاعدة في معادلة التعادل الموزونة. عند نقطة التكافؤ تتساوى مولات H⁺ وOH⁻. يختار الكاشف بحيث يتغير لونه عند pH نقطة التكافؤ.', '\dfrac{M_a V_a}{a} = \dfrac{M_b V_b}{b}', 1, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('e196d866-9f12-59fe-9ee9-5a8fe9a3fac4', '7e2b03eb-1adb-5ffa-aaad-dde868c933d8', 'المعادلة الأيونية لتفاعل التعادل بين حمض قوي وقاعدة قوية هي:', 'الأيونات المتفرجة (Na⁺ وCl⁻) لا تشارك، وجوهر التفاعل اتحاد H⁺ مع OH⁻ لتكوين الماء.', 1, 'editorial'),
 ('a0f77940-685c-5070-8051-1b854d9d97cd', '7e2b03eb-1adb-5ffa-aaad-dde868c933d8', 'نقطة التكافؤ في المعايرة هي النقطة التي:', 'عندها يكون الحمض والقاعدة قد تفاعلا تمامًا بنسبة المعادلة.', 1, 'editorial'),
 ('3863603f-8f04-5d63-ac01-bc9b1fe3630f', '7e2b03eb-1adb-5ffa-aaad-dde868c933d8', '20 mL من محلول HCl تركيزه 0.2 M يتعادل تمامًا مع محلول NaOH تركيزه 0.1 M. ما حجم NaOH اللازم؟', 'n(HCl) = 0.2 × 0.02 = 0.004 mol، والحجم = 0.004 / 0.1 = 0.04 L = 40 mL.', 2, 'editorial'),
 ('ac34b38d-3858-5c75-a8f2-11a10bd29989', '7e2b03eb-1adb-5ffa-aaad-dde868c933d8', '25 mL من محلول H₂SO₄ احتاجت 50 mL من محلول NaOH تركيزه 0.1 M للتعادل التام. ما تركيز H₂SO₄؟', 'n(NaOH) = 0.1 × 0.05 = 0.005 mol، وH₂SO₄ + 2NaOH فيكون n(H₂SO₄) = 0.0025 mol، والتركيز = 0.0025 / 0.025 = 0.1 M.', 2, 'editorial'),
 ('0d5faa40-9b6a-5696-b8cd-e773ad138ee5', '7e2b03eb-1adb-5ffa-aaad-dde868c933d8', 'عند معايرة حمض الخليك CH₃COOH (ضعيف) بمحلول NaOH فإن الكاشف المناسب هو:', 'ملح CH₃COONa قاعدي، فتقع نقطة التكافؤ في الوسط القاعدي وينفع الفينولفثالين.', 2, 'editorial'),
 ('aefeafce-8038-55d5-b713-3e49ac15f07d', '7e2b03eb-1adb-5ffa-aaad-dde868c933d8', 'خلط 50 mL من HCl تركيزه 0.1 M مع 50 mL من NaOH تركيزه 0.2 M. ما قيمة pH للمحلول الناتج؟ (log 5 = 0.7)', 'n(OH⁻) المتبقي = 0.01 - 0.005 = 0.005 mol في 0.1 L فيكون [OH⁻] = 0.05 M وpOH = 1.3 وبذلك pH = 14 - 1.3 = 12.7.', 3, 'editorial');
