INSERT INTO concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) VALUES ('42508e7c-b327-53fc-aaf6-01a5d75aa3b2', '9558ef81-c159-56ec-8f51-b431386a3ac4', 'تميؤ الأملاح', 'تميؤ الملح هو تفاعل أيوناته مع الماء. أيونات الحمض القوي أو القاعدة القوية (Cl⁻ وNa⁺ مثلًا) لا تتميأ. أيون الحمض الضعيف (مثل CH₃COO⁻ وCO₃²⁻) يتميأ فيعطي OH⁻ ويكون المحلول قاعديًا. أيون القاعدة الضعيفة (مثل NH₄⁺) يتميأ فيعطي H₃O⁺ ويكون المحلول حمضيًا.', 'A^- + H_2O \rightleftharpoons HA + OH^-', 2, 'editorial');
INSERT INTO questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) VALUES
 ('60600e1d-b600-5a85-91dd-d8828556e16b', '42508e7c-b327-53fc-aaf6-01a5d75aa3b2', 'تميؤ الملح هو:', 'تميؤ الملح تفاعل أحد أيوناته على الأقل مع الماء ليغير pH المحلول.', 1, 'editorial'),
 ('28a25719-cb0b-51b4-a1c2-24d5c83aea00', '42508e7c-b327-53fc-aaf6-01a5d75aa3b2', 'محلول كلوريد الصوديوم NaCl في الماء يكون:', 'NaCl ناتج من حمض قوي HCl وقاعدة قوية NaOH ولا يتميأ أي من أيونيه.', 1, 'editorial'),
 ('15a507ef-70dc-565d-8949-67edf304a071', '42508e7c-b327-53fc-aaf6-01a5d75aa3b2', 'أي الأملاح الآتية يعطي محلولًا قاعديًا عند ذوبانه في الماء؟', 'CO₃²⁻ قاعدة مرافقة لحمض ضعيف (HCO₃⁻) فيتميأ معطيًا أيونات OH⁻.', 2, 'editorial'),
 ('4a2a8b43-c2a4-57d4-88ef-60bc5c78887c', '42508e7c-b327-53fc-aaf6-01a5d75aa3b2', 'أي الأملاح الآتية يعطي محلولًا حمضيًا عند ذوبانه في الماء؟', 'NH₄⁺ حمض مرافق لقاعدة ضعيفة فيعطي H₃O⁺، أما Cl⁻ فلا يتميأ.', 2, 'editorial'),
 ('ecfb883c-b38b-56f4-9aa6-02d984cb8b21', '42508e7c-b327-53fc-aaf6-01a5d75aa3b2', 'معادلة تميؤ أيون الأسيتات في محلول CH₃COONa هي:', 'الأسيتات قاعدة مرافقة تستقبل بروتونًا من الماء فتتكون CH₃COOH وOH⁻، ولذلك يكون المحلول قاعديًا.', 3, 'editorial'),
 ('b01d6a4e-d016-5757-bbe1-dee422362531', '42508e7c-b327-53fc-aaf6-01a5d75aa3b2', 'محلول خلات الأمونيوم CH₃COONH₄ يكون تقريبًا متعادلًا لأن:', 'يتميأ الأيونان معًا، والأسيتات يعطي OH⁻ بنفس القدر تقريبًا الذي يعطي به NH₄⁺ أيون H₃O⁺ لأن Ka(CH₃COOH) ≈ Kb(NH₃) ≈ 1.8 × 10⁻⁵.', 3, 'editorial');
